UPDATE t_p5815085_family_assistant_pro.notifications
SET title = 'Уточнение по обращению: добавление лекарства',
    message = E'Сергей, добрый день!\n\nВ нашем прошлом сообщении мы поторопились: мы пока не смогли точно воспроизвести вашу ошибку и не можем гарантировать, что она исправлена. Мы продолжаем разбираться.\n\nПомогите, пожалуйста: попробуйте добавить лекарство ещё раз и напишите, что видите на экране (точный текст сообщения, на каком шаге), в каком браузере и на каком устройстве. Если можно, пришлите скриншот.\n\nМы зачислили 500 ₽ на семейный кошелёк как благодарность за обращение. Списания идут за запросы к ИИ-функциям. Актуальные цены показаны в разделе «Кошелёк».\n\nКак только исправление будет проверено на рабочем сервисе, мы сообщим отдельно.\n\nС уважением, команда «Наша Семья»',
    status = 'sent'
WHERE id = 'b38fa425-d7cb-4d5a-9ab1-999d1295adbb'
  AND user_id = 'f4714c96-12e6-4051-82f3-b9549ec2e2a3'
  AND type = 'support_reply';